import {t,message,messageText,LocalisedError,LANGUAGES,getLocale,setLocale,onLocaleChange,applyDocumentLocale,formatDate,formatDateRange,formatTime,formatNumber,formatPercent,formatClock,formatDuration,formatHours,firstWeekday,localeWeekStart,weekdayNames,formatDateInput,parseDateInput} from './i18n.mjs';
import {dateField,closeDatePicker,initDateInputs} from './date-input.mjs';
import {COLORS,uid,dayKey,parseDay,addDays,calendarDays,esc,newState,elapsed,startTimer,pauseTimer,finishTimer,aggregate,streak,validateState,allSessions,hasActiveSession,heatPalette,restoreLocalState,LIMITS,MAX_BACKUP_BYTES,backupState,serializeBackup,parseBackup} from './core.mjs';
import {withStudyLock} from './storage.mjs';
import {THEME_OPTIONS,getThemeByKey,getThemeTokens} from './vendor/themes.mjs';
import * as cloud from './cloud.mjs';

const KEY='sela.study.v1', app=document.querySelector('#app'), modal=document.querySelector('#modal');
let memoryOnly=false, needsReset=false, cloudStatus='', authPending=false, cloudPending='', renderedView='', uiEpoch=0, modalOpener='', importEpoch=0;
let state, unreadableRaw='', storedRaw=null, storageIssue='', view='study', period='week', cursor=new Date(), heatMode='contributions', taskDate=dayKey(), taskFilter='all', focused=false, calendarToday=dayKey();
try{storedRaw=localStorage.getItem(KEY);const restored=restoreLocalState(storedRaw);state=restored.state;needsReset=restored.reset;}catch(e){state=newState();if(storedRaw){unreadableRaw=storedRaw;storageIssue=message('error.unreadable');}else{memoryOnly=true;storageIssue=message('error.storageUnavailable');}}
const icons={timer:'<circle cx="12" cy="13" r="8"/><path d="M12 9v4l2 2M9 2h6M12 2v3M18 5l2-2"/>',chart:'<path d="M4 4v16h16M8 16v-5M13 16V7M18 16v-8"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4M17 3v4M3 10h18M8 14h1M14 14h1M8 18h1"/>',book:'<path d="M12 6c-3-3-7-3-10-2v15c4-1 7-1 10 2 3-3 6-3 10-2V4c-3-1-7-1-10 2v15"/>',settings:'<path d="m9 3 1-1h4l1 3 3 1 3-1 2 4-2 2v3l2 2-2 4-3-1-3 1-1 3h-4l-1-3-3-1-3 1-2-4 2-2v-3l-2-2 2-4 3 1 3-1z" transform="translate(0 -1) scale(.95)"/><circle cx="12" cy="12" r="3"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1"/>',moon:'<path d="M20 14A8 8 0 0 1 10 4a8 8 0 1 0 10 10Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',play:'<path d="m9 5 11 7-11 7Z"/>',pause:'<path d="M8 5v14M16 5v14"/>',stop:'<rect x="6" y="6" width="12" height="12" rx="2"/>',arrow:'<path d="m14 6-6 6 6 6"/>',check:'<path d="m5 12 4 4 10-10"/>',fire:'<path d="M12 3c3 5-1 6 2 9 2-1 3-3 3-3 4 5 3 12-5 12S2 14 7 8c-1 4 2 5 3 4 2-2 0-5 2-9Z"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',edit:'<path d="m15 4 5 5M4 20l4-1L21 6l-4-4L4 15Z"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',expand:'<path d="M8 3H3v5M16 3h5v5M21 16v5h-5M3 16v5h5"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4"/>',cloud:'<path d="M7 18a5 5 0 1 1 0-10 6 6 0 0 1 11-1 5 5 0 0 1-1 11Z"/>',list:'<path d="M9 6h12M9 12h12M9 18h12M3 6h1M3 12h1M3 18h1"/>',monitor:'<rect x="3" y="3" width="18" height="14" rx="2"/><path d="M8 21h8M12 17v4"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.book}</svg>`;
const button=(action,label,ic='',classes='',extra='')=>`<button type="button" class="btn ${classes}" data-action="${action}" ${extra}>${ic?icon(ic):''}${esc(label)}</button>`;
const fmtDate=formatDate,ht=(key,params)=>esc(t(key,params));
// setFullYear preserves years 1–99 instead of applying Date's 1900 offset.
const monthDate=(v,offset=0,day=1)=>{const d=addDays(v,0);d.setFullYear(d.getFullYear(),d.getMonth()+offset,day);d.setHours(0,0,0,0);return d;};
const subject=id=>state.subjects.find(x=>x.id===id);
const dot=s=>`<span class="subject-dot" style="--subject:${s?.color||'#888888'}" aria-hidden="true"></span>`;
const subjectOptions=(selected='',empty=false)=>`${empty?`<option value="">${ht('subjects.noneOption')}</option>`:''}${state.subjects.filter(x=>!x.archived||x.id===selected).map(x=>`<option value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x.name)}</option>`).join('')}`;
function toast(value){toastMessage=value;const el=document.querySelector('#toast');el.textContent=messageText(value);el.classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>{el.classList.remove('show');toastMessage=null;},4500);}
function persist(next) {
 const valid=validateState(next);valid.updatedAt=Date.now();const raw=JSON.stringify(valid);
 try{localStorage.setItem(KEY,raw);storedRaw=raw;memoryOnly=false;storageIssue='';unreadableRaw='';}
 catch{memoryOnly=true;storageIssue=message('error.storageFull');toast(storageIssue);}
 state=valid;render();
}
function latestState() {
 if(unreadableRaw)throw new LocalisedError('error.recoveryFirst');
 let raw;try{raw=localStorage.getItem(KEY);}catch{if(memoryOnly)return structuredClone(state);throw new LocalisedError('error.storageRead');}
 if(memoryOnly){if(raw!==storedRaw)throw new LocalisedError('error.tabConflict');return structuredClone(state);}
 return restoreLocalState(raw).state;
}
function mutate(fn){return withStudyLock(()=>{const next=latestState();const result=fn(next);persist(next);return result;});}
function replaceData(next,{recover=false,expectedRaw=storedRaw,beforeReplace=()=>{}}={}){return withStudyLock(()=>{
 if(recover||unreadableRaw){let raw;try{raw=localStorage.getItem(KEY);}catch{throw new LocalisedError('error.storageRead');}if(raw!==expectedRaw)throw new LocalisedError('error.tabConflict');}
 const current=recover||unreadableRaw?state:latestState();
 if(hasActiveSession(current))throw new LocalisedError('error.finishReplace');
 beforeReplace();exportData(current);persist(next);
});}
function applyTheme(){const mode=state.settings.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):state.settings.theme;const t=getThemeTokens(state.settings.themeKey,mode);for(const[k,v]of Object.entries(t)){if(typeof v==='string')document.documentElement.style.setProperty('--'+k.replace(/[A-Z]/g,m=>'-'+m.toLowerCase()),v);}const theme=getThemeByKey(state.settings.themeKey);document.documentElement.style.setProperty('--layout-panel-radius',theme.layout.panelRadius);heatPalette(t).forEach((c,i)=>{document.documentElement.style.setProperty('--heat-bg-'+i,c.background);document.documentElement.style.setProperty('--heat-text-'+i,c.text);});document.documentElement.style.colorScheme=mode;document.body.dataset.resolvedMode=mode;document.querySelector('meta[name="theme-color"]').content=t.paper;}
function statCards(a=aggregate(state,dayKey(),dayKey())){
 return `<div class="summary-grid"><div class="summary-item">${icon('timer')}<div><span>${ht('summary.today')}</span><strong data-live="today">${formatClock(a.total)}</strong></div></div><div class="summary-item">${icon('target')}<div><span>${ht('summary.goal')}</span><strong><span data-live="today-minutes">${formatNumber(Math.floor(a.total/60000))}</span> <small>${ht('summary.goalValue',{goal:state.settings.goal})}</small></strong></div><span class="summary-progress" data-live="goal-percent">${formatPercent(Math.min(1,a.total/(state.settings.goal*60000)))}</span></div><div class="summary-item"><div><span>${ht('summary.consistency')}</span><strong class="streak-value" data-live="streak">${ht('summary.streak',{count:streak(state)})}</strong></div></div></div>`;
}
function timerCard(){
 const timer=state.timer,chosen=subject(timer.subjectId),running=timer.startedAt!==null,hasSubjects=state.subjects.some(x=>!x.archived);
 return `<section class="panel timer-panel ${running?'running':''}" aria-labelledby="timer-heading"><div class="panel-top"><h2 id="timer-heading">${ht('timer.heading')}</h2>${button('focus','',focused?'close':'expand','icon-btn',`aria-label="${ht(focused?'timer.exitFocus':'timer.focus')}" title="${ht('timer.focus')}"`)}</div><div class="timer-center"><label class="timer-subject">${dot(chosen)}<select id="timer-subject" aria-label="${ht('timer.subject')}" ${hasActiveSession(state)||!hasSubjects?'disabled':''}>${hasSubjects?subjectOptions(timer.subjectId):`<option>${ht('timer.choosePrompt')}</option>`}</select></label><div class="timer-digits" data-live="timer" aria-label="${ht('timer.elapsed')}">${formatClock(elapsed(state))}</div><p class="timer-status" data-live="status">${ht(!hasSubjects?'timer.empty':running?'timer.runningHint':hasActiveSession(state)?'timer.pausedHint':'timer.readyHint')}</p><div class="timer-actions">${hasSubjects?button('toggle-timer',t(running?'timer.pause':hasActiveSession(state)?'timer.resume':'timer.start'),running?'pause':'play','primary',`data-running="${running}" data-run-id="${timer.runId}"`):button('add-subject',t('subjects.add'),'plus','primary')}${button('finish',t('timer.finish'),'stop','quiet',`data-run-id="${timer.runId}" ${!hasActiveSession(state)?'disabled':''}`)}</div></div><div class="timer-bottom"><span class="status-dot ${running?'live':''}"></span><span>${ht(running?'timer.running':hasActiveSession(state)?'timer.paused':'timer.ready')}</span><span>${ht('timer.stopwatch')}</span></div></section>`;
}
function tasksCard(){
 const tasks=state.tasks.filter(x=>x.date===taskDate),visible=tasks.filter(x=>taskFilter!=='active'||!x.done),done=tasks.filter(x=>x.done).length;
 return `<section class="panel tasks-panel"><div class="panel-top"><h2>${taskDate===dayKey()?ht('tasks.today'):ht('tasks.dateHeading',{date:fmtDate(parseDay(taskDate),{day:'numeric',month:'short'})})}</h2><span class="pill">${ht('tasks.progress',{done,total:tasks.length})}</span></div><div class="task-filter"><div class="tabs"><button data-action="task-filter" data-value="all" aria-pressed="${taskFilter==='all'}">${ht('tasks.all')}</button><button data-action="task-filter" data-value="active" aria-pressed="${taskFilter==='active'}">${ht('tasks.active')}</button></div>${dateField('task-date','',taskDate,t('tasks.date'))}</div><div class="task-list">${visible.length?visible.map(x=>{const s=subject(x.subjectId);return `<div class="task ${x.done?'done':''}"><label><input type="checkbox" data-task="${esc(x.id)}" ${x.done?'checked':''}><span class="check-box">${icon('check')}</span><span class="task-copy"><span>${esc(x.title)}</span><small>${s?dot(s)+esc(s.name):ht('tasks.independent')}</small></span></label><div class="task-tools">${button('edit-task','','edit','icon-btn',`data-id="${x.id}" aria-label="${ht('tasks.editNamed',{title:x.title})}"`)}${button('delete-task','','trash','icon-btn',`data-id="${x.id}" aria-label="${ht('tasks.deleteNamed',{title:x.title})}"`)}</div></div>`;}).join(''):`<div class="empty">${icon('list')}<p>${ht(tasks.length?'tasks.completeEmpty':'tasks.empty')}</p><small>${ht(tasks.length?'tasks.break':'tasks.first')}</small></div>`}</div>${button('add-task',t('tasks.add'),'plus','add-row')}</section>`;
}
function subjectRows(a,compact=false){
 const items=state.subjects.filter(x=>!x.archived||a.subjects[x.id]).map(x=>({...x,ms:a.subjects[x.id]||0})).sort((a,b)=>b.ms-a.ms);
 return items.length?items.map(x=>`<div class="subject-row"><div class="subject-name">${dot(x)}<span>${esc(x.name)}${x.archived?`<small>${ht('subjects.archivedSuffix')}</small>`:''}</span></div><div class="subject-track"><span data-subject-progress="${x.id}" style="width:${a.total?x.ms/a.total*100:0}%;background:${x.color}"></span></div><span class="mono" data-subject-time="${x.id}">${formatDuration(x.ms)}</span>${compact?button('choose-subject','','play','icon-btn',`data-id="${x.id}" aria-label="${ht('subjects.studyNamed',{name:x.name})}" ${x.archived||hasActiveSession(state)?'disabled':''}`):''}</div>`).join(''):`<div class="empty"><p>${ht('subjects.emptyDashboard')}</p></div>`;
}
function level(ms){return ms===0?0:ms<3600000?1:ms<7200000?2:ms<14400000?3:4;}
function heatCell(d,days,other=false){
 const key=dayKey(d),ms=days[key]||0,future=key>dayKey();
 return `<button class="heat-cell l${level(ms)} ${key===dayKey()?'today':''} ${other?'other':''}" data-action="day-detail" data-date="${key}" ${future?'disabled':''} title="${esc(fmtDate(d))} · ${formatDuration(ms)}" aria-label="${ht('calendar.dayLabel',{date:fmtDate(d),time:formatClock(ms)})}">${heatMode==='month'?formatNumber(d.getDate()):''}</button>`;
}
function heatmapCard(full=false){
 const start=monthDate(cursor),end=monthDate(cursor,1,0),a=aggregate(state,dayKey(addDays(start,-92)),dayKey(addDays(end,7))),all=aggregate(state,dayKey(start),dayKey(end));let grid='';
 if(heatMode==='contributions'){
  const to=parseDay(dayKey()),first=addDays(to,-89),from=localeWeekStart(first),weekdays=weekdayNames();let weeks=0;for(let d=from;d<=to;d=addDays(d,7))weeks++;let labels='';
  for(let w=0;w<weeks;w++){const d=addDays(from,w*7),labelDate=w===0?first:d;labels+=`<span>${w===0||d.getDate()<=7&&d.getMonth()!==first.getMonth()?fmtDate(labelDate,{month:'short'}):''}</span>`;}
  const aa=aggregate(state,dayKey(from),dayKey(to));
  grid=`<div class="contribution-wrap"><div class="day-labels">${[0,2,4].map(i=>`<span>${esc(weekdays[i])}</span>`).join('')}</div><div class="contribution-content"><div class="month-labels" style="--weeks:${weeks}">${labels}</div><div class="contribution-grid" style="--weeks:${weeks}">${calendarDays(from,weeks*7).map(d=>{return !d||d<first?'<span class="heat-cell l0 padding" aria-hidden="true"></span>':heatCell(d,aa.days)}).join('')}</div></div></div>`;
 }else if(heatMode==='week'){
  const from=localeWeekStart(cursor);
  grid=`<div class="week-heat">${calendarDays(from,7).map((d,i)=>{if(!d)return `<div><span>${esc(weekdayNames()[i])}</span><span class="heat-cell padding" aria-hidden="true"></span></div>`;const ms=a.days[dayKey(d)]||0;return `<div><span>${fmtDate(d,{weekday:'short'})}</span>${heatCell(d,a.days)}<strong>${formatNumber(d.getDate())}</strong><small data-heat-day="${dayKey(d)}">${formatDuration(ms)}</small></div>`;}).join('')}</div>`;
 }else{
  const from=localeWeekStart(start),count=Math.ceil((((start.getDay()-firstWeekday()+7)%7)+end.getDate())/7)*7;
  grid=`<div class="calendar-grid">${weekdayNames().map(x=>`<span class="calendar-label">${esc(x)}</span>`).join('')}${calendarDays(from,count).map(d=>d?heatCell(d,a.days,d.getMonth()!==start.getMonth()):'<span class="heat-cell padding" aria-hidden="true"></span>').join('')}</div>`;
 }
 const from=localeWeekStart(cursor),weekTotal=aggregate(state,dayKey(from),dayKey(addDays(from,6))).total;
 return `<section class="panel heatmap-panel"><div class="panel-top"><div><h2>${ht('calendar.heading')}</h2><p>${ht('calendar.intro')}</p></div><div class="tabs">${[['contributions','calendar.ninety'],['week','calendar.week'],['month','calendar.month']].map(([value,key])=>`<button data-action="heat-mode" data-value="${value}" aria-pressed="${heatMode===value}">${ht(key)}</button>`).join('')}</div></div>${heatMode!=='contributions'?`<div class="period-nav">${button('heat-prev','','arrow','icon-btn',`aria-label="${ht('calendar.previous')}"`)}<strong>${heatMode==='month'?fmtDate(start,{month:'long',year:'numeric'}):formatDateRange(from,addDays(from,6))}</strong>${button('heat-next','','arrow','icon-btn forward',`aria-label="${ht('calendar.next')}"`)}</div>`:''}${grid}<div class="heatmap-footer"><span data-live="heat-total">${heatMode==='contributions'?ht('calendar.trail'):ht(heatMode==='week'?'calendar.weekTotal':'calendar.monthTotal',{duration:formatDuration(heatMode==='week'?weekTotal:all.total)})}</span><div class="legend"><span>${ht('calendar.less')}</span>${[0,1,2,3,4].map(i=>`<span class="heat-sample l${i}"></span>`).join('')}<span>${ht('calendar.more')}</span></div></div>${full?`<div class="calendar-info">${ht('calendar.help')}</div>`:''}</section>`;
}
function studyView(){const a=aggregate(state,dayKey(),dayKey());return `${statCards(a)}<div class="study-grid">${timerCard()}${tasksCard()}</div><div class="bottom-grid">${heatmapCard()}<section class="panel subjects-panel" data-today-subjects><div class="panel-top"><h2>${ht('summary.today')}</h2>${button('nav',t('subjects.manage'),'','text-button','data-view="subjects"')}</div>${subjectRows(a,true)}<div class="panel-note"><span data-live="session-count">${ht('count.sessions',{count:a.count})}</span> · ${ht('stats.longest')} <span data-live="max-focus">${formatDuration(a.max)}</span></div></section></div>`;}
function range(){const d=parseDay(dayKey(cursor));if(period==='day')return[d,d];if(period==='week'){const from=localeWeekStart(d);return[from,addDays(from,6)];}return[monthDate(d),monthDate(d,1,0)];}
function statsView(){
 const [from,to]=range(),a=aggregate(state,dayKey(from),dayKey(to)),days=[];for(let d=from;d<=to;d=addDays(d,1))days.push(d);
 const max=Math.max(3600000,...Object.values(a.days)),sessions=allSessions(state).filter(x=>x.end>+from&&x.start<+addDays(to,1)).map(x=>({...x,periodMs:Math.max(0,Math.min(x.end,+addDays(to,1))-Math.max(x.start,+from))})).sort((a,b)=>b.start-a.start);
 return `<div class="page-toolbar"><div class="tabs">${[['day','stats.daily'],['week','stats.weekly'],['month','stats.monthly']].map(([value,key])=>`<button data-action="period" data-value="${value}" aria-pressed="${period===value}">${ht(key)}</button>`).join('')}</div><div class="period-nav">${button('period-prev','','arrow','icon-btn',`aria-label="${ht('calendar.previous')}"`)}<strong>${period==='month'?fmtDate(from,{month:'long',year:'numeric'}):period==='day'?fmtDate(from):formatDateRange(from,to)}</strong>${button('period-next','','arrow','icon-btn forward',`aria-label="${ht('calendar.next')}"`)}${button('period-today',t('stats.now'),'','text-button')}</div></div><div class="summary-grid stats-summary"><div class="summary-item"><div><span>${ht('stats.total')}</span><strong>${formatClock(a.total)}</strong></div></div><div class="summary-item"><div><span>${ht('stats.average')}</span><strong>${formatDuration(a.total/days.length)}</strong></div></div><div class="summary-item"><div><span>${ht('stats.longest')}</span><strong>${formatDuration(a.max)} <small>· ${ht('count.sessions',{count:a.count})}</small></strong></div></div></div><div class="stats-grid"><section class="panel"><div class="panel-top"><h2>${ht('stats.rhythm')}</h2><span class="muted">${ht('stats.hours')}</span></div>${period==='day'?timeline(a):`<div class="bar-chart" role="img" aria-label="${ht('stats.chartLabel')}"><div class="chart-axis"><span>${formatHours(max/3600000)}</span><span>${formatHours(max/7200000)}</span><span>${formatNumber(0)}</span></div><div class="bar-columns">${days.map(d=>{const ms=a.days[dayKey(d)]||0;return `<button class="bar-column" data-action="day-detail" data-date="${dayKey(d)}" aria-label="${ht('calendar.dayLabel',{date:fmtDate(d),time:formatDuration(ms)})}" title="${esc(fmtDate(d))}: ${formatDuration(ms)}"><span class="bar" style="height:${ms/max*100}%;min-height:${ms?4:0}px"></span><span class="bar-label">${period==='week'?fmtDate(d,{weekday:'short'}):formatNumber(d.getDate())}</span></button>`;}).join('')}</div></div>`}<div class="panel-note">${ht('stats.activeDays',{count:Object.keys(a.days).length})}</div></section><section class="panel"><div class="panel-top"><h2>${ht('stats.bySubject')}</h2></div>${subjectRows(a)}</section></div><section class="panel history-panel"><div class="panel-top"><h2>${ht('stats.history')}</h2><span class="muted">${ht('count.records',{count:sessions.length})}</span></div><div class="table-scroll"><table><thead><tr>${['subject','date','start','duration','status'].map(key=>`<th>${ht('table.'+key)}</th>`).join('')}</tr></thead><tbody>${sessions.slice(0,100).map(x=>`<tr><td>${dot(subject(x.subjectId))}${esc(subject(x.subjectId)?.name||t('subjects.generic'))}</td><td>${fmtDate(x.start,{day:'numeric',month:'short'})}</td><td class="mono">${formatTime(x.start)}</td><td class="mono" title="${ht('table.segment',{time:formatClock(x.durationMs)})}">${formatClock(x.periodMs)}</td><td><span class="pill">${ht(x.id.startsWith('active:')?'table.running':'table.recorded')}</span></td></tr>`).join('')||`<tr><td colspan="5" class="empty">${ht('table.empty')}</td></tr>`}</tbody></table></div>${sessions.length>100?`<p class="panel-note">${ht('table.limited')}</p>`:''}</section>`;
}
function timeline(a){return `<div class="timeline">${a.parts.length?a.parts.map(x=>`<div class="timeline-row"><span class="mono">${formatTime(x.start)}</span><div>${dot(subject(x.subjectId))}<strong>${esc(subject(x.subjectId)?.name)}</strong><small>${formatClock(x.ms)}</small></div></div>`).join(''):`<div class="empty"><p>${ht('timeline.empty')}</p></div>`}</div>`;}
function subjectsView(){
 const totals=Object.create(null);for(const interval of allSessions(state))totals[interval.subjectId]=(totals[interval.subjectId]||0)+interval.durationMs;
 return `<div class="page-toolbar"><p class="muted">${ht('subjects.intro')}</p>${button('add-subject',t('subjects.add'),'plus','primary')}</div><section class="panel subject-manager">${state.subjects.filter(x=>!x.archived).map(x=>`<div class="managed-subject"><div class="subject-symbol" style="--subject:${x.color}">${icon('book')}</div><div><h2>${esc(x.name)}</h2><p>${ht('subjects.total',{duration:formatDuration(totals[x.id]||0)})} · ${ht('count.records',{count:state.sessions.filter(y=>y.subjectId===x.id).length})}</p></div><div class="managed-actions">${button('choose-subject',t('subjects.study'),'play','quiet',`data-id="${x.id}" ${hasActiveSession(state)?'disabled':''}`)}${button('edit-subject','','edit','icon-btn',`data-id="${x.id}" aria-label="${ht('subjects.editNamed',{name:x.name})}"`)}${button('delete-subject','','trash','icon-btn',`data-id="${x.id}" aria-label="${ht('subjects.archiveNamed',{name:x.name})}"`)}</div></div>`).join('')||`<div class="empty"><p>${ht('subjects.empty')}</p><small>${ht('subjects.first')}</small></div>`}</section>${state.subjects.some(x=>x.archived)?`<section class="panel"><div class="panel-top"><h2>${ht('subjects.archiveHeading')}</h2></div><p class="muted">${ht('subjects.archiveNote')}</p>${state.subjects.filter(x=>x.archived).map(x=>`<div class="archive-row"><span>${dot(x)}${esc(x.name)}</span><div class="managed-actions">${button('edit-subject','','edit','icon-btn',`data-id="${x.id}" aria-label="${ht('subjects.editArchive',{name:x.name})}"`)}${button('restore-subject',t('subjects.restore'),'','quiet',`data-id="${x.id}"`)}</div></div>`).join('')}</section>`:''}`;
}
function languageSelect(){return `<label class="field">${ht('settings.language')}<select id="language-select">${LANGUAGES.map(l=>`<option value="${l.code}" lang="${l.code}" ${l.code===getLocale()?'selected':''}>${esc(l.name)}</option>`).join('')}</select></label>`;}
function settingsView(){
 const config=cloud.getConfig(),busy=authPending||cloudPending,themeName=t('theme.'+getThemeByKey(state.settings.themeKey).key);
 return `<div class="settings-grid"><section class="panel"><div class="panel-top"><h2>${ht('settings.appearance')}</h2></div>${languageSelect()}<p class="small muted">${ht('settings.languageHelp')}</p><div class="field"><span>${ht('settings.mode')}</span><div class="mode-options">${[['light','settings.light','sun'],['dark','settings.dark','moon'],['system','settings.system','monitor']].map(([value,key,ic])=>button('theme',t(key),ic,state.settings.theme===value?'selected':'quiet',`data-value="${value}" aria-pressed="${state.settings.theme===value}"`)).join('')}</div></div><label class="field">${ht('settings.colourTheme')}<select id="theme-select">${['classic','light','dark'].map(c=>`<optgroup label="${ht(c==='classic'?'settings.classic':c==='light'?'settings.lightCollection':'settings.darkCollection')}">${THEME_OPTIONS.filter(x=>x.collection===c).map(x=>`<option value="${x.key}" ${x.key===state.settings.themeKey?'selected':''}>${ht('theme.'+x.key)}</option>`).join('')}</optgroup>`).join('')}</select></label><div class="theme-preview">${getThemeByKey(state.settings.themeKey).colors.map(c=>`<span style="background:${c}"></span>`).join('')}<p>${esc(themeName)}</p></div><label class="field">${ht('settings.interface')}<select id="interface-select"><option value="studio" ${state.settings.interfaceStyle==='studio'?'selected':''}>${ht('settings.studio')}</option><option value="opaline" ${state.settings.interfaceStyle==='opaline'?'selected':''}>${ht('settings.opaline')}</option></select></label><p class="small muted">${ht('settings.themeSource')}</p></section><section class="panel"><div class="panel-top"><h2>${ht('settings.goalHeading')}</h2></div><form id="goal-form" novalidate><label class="field">${ht('settings.goalInput')}<input name="goal" type="number" min="15" max="1440" step="1" value="${state.settings.goal}" required></label><p class="muted">${ht('settings.goalHint')}</p><p class="form-error" role="alert"></p><button class="btn primary" type="submit">${ht('settings.goalSave')}</button></form></section><section class="panel"><div class="panel-top"><h2>${ht('settings.data')}</h2>${icon('download')}</div><p>${ht('settings.dataHelp')}</p><div class="button-row">${button('export',t('data.export'),'download','primary')}${button('import',t('data.import'),'upload','quiet')}</div><input id="import-file" type="file" accept="application/json,.json" hidden><div class="data-status">${icon('check')} ${ht(unreadableRaw?'data.recovery':memoryOnly?'data.temporary':'data.local')}</div><p class="small muted">${ht('data.noCredentials')}</p></section><section class="panel"><div class="panel-top"><h2>Supabase</h2>${icon('cloud')}</div><p>${ht('cloud.intro')}</p><form id="cloud-config" novalidate aria-busy="${!!busy}"><label class="field">${ht('cloud.url')}<input name="url" ${busy?'disabled':''} type="url" placeholder="https://project.supabase.co" value="${esc(config.url||'')}" required></label><label class="field">${ht('cloud.key')}<input name="key" ${busy?'disabled':''} type="password" autocomplete="off" placeholder="sb_publishable_..." value="${esc(config.key||'')}" required></label><p class="form-error" role="alert"></p><button class="btn quiet" type="submit" ${busy?'disabled':''}>${ht('cloud.configSave')}</button></form><p class="small muted">${t('cloud.schemaInstruction',{schema:`<a href="supabase-schema.sql" download>${ht('cloud.schema')}</a>`})} <a href="panduan-supabase.html" target="_blank" rel="noopener">${ht('cloud.guide')}</a></p>${config.url?`<form id="cloud-auth" novalidate aria-busy="${authPending}"><label class="field">${ht('cloud.email')}<input name="email" type="email" autocomplete="email" required></label><label class="field">${ht('cloud.password')}<input name="password" type="password" minlength="8" autocomplete="current-password" required></label><p class="form-error" role="alert"></p><div class="button-row"><button class="btn primary" type="submit" name="mode" value="login" ${busy?'disabled':''}>${ht('cloud.login')}</button><button class="btn quiet" type="submit" name="mode" value="signup" ${busy?'disabled':''}>${ht('cloud.signup')}</button></div></form><div class="button-row cloud-actions">${button('cloud-save',t(cloudPending==='save'?'cloud.processing':'cloud.save'),'upload','quiet',busy?'disabled':'')}${button('cloud-load',t(cloudPending==='load'?'cloud.loading':'cloud.load'),'download','quiet',busy?'disabled':'')}${button('cloud-out',t(cloudPending==='out'?'cloud.signingOut':'cloud.out'),'','text-button',busy?'disabled':'')}</div>`:''}<p id="cloud-status" class="small muted">${esc(messageText(cloudStatus||message(config.url?'cloud.configured':'cloud.notConfigured')))}</p></section></div>`;
}

function focusSelectorFor(active){
 if(!active||!app.contains(active))return '';
 if(active.id)return '#'+CSS.escape(active.id);
 if(active.dataset.task)return '[data-task="'+CSS.escape(active.dataset.task)+'"]';
 if(active.dataset.action){let selector='[data-action="'+CSS.escape(active.dataset.action)+'"]';for(const k of ['id','value','view'])if(active.dataset[k])selector+='[data-'+k+'="'+CSS.escape(active.dataset[k])+'"]';return selector;}
 const form=active.closest?.('form');return form?.id&&active.name?'#'+CSS.escape(form.id)+' [name="'+CSS.escape(active.name)+'"]':'';
}
function captureDrafts(discard=[]){
 if(view!=='settings'||renderedView!==view)return [];
 return [...app.querySelectorAll('#goal-form input, #cloud-config input, #cloud-auth input')].filter(el=>!discard.includes(el.closest('form').id)&&el.value!==el.defaultValue).map(el=>({selector:'#'+el.closest('form').id+' [name="'+el.name+'"]',value:el.value}));
}
async function withCloudOperation(kind,fn){
 if(authPending||cloudPending)throw new LocalisedError('error.cloudBusy');
 cloudPending=kind;render();try{return await fn();}finally{cloudPending='';if(view==='settings')render();}
}
function updateTitle(){document.title=state.timer.startedAt!==null?`${formatClock(elapsed(state))} · ${subject(state.timer.subjectId)?.name||t('subjects.generic')} — sela.`:`sela. — ${t('nav.study')}`;}
const formErrors=new Map();let modalContext=null,toastMessage=null;
function render({discardDrafts=[]}={}){
 const active=document.activeElement,focusSelector=focusSelectorFor(active),drafts=captureDrafts(discardDrafts);let selection;
 try{if(active?.selectionStart!==null)selection=[active.selectionStart,active.selectionEnd];}catch{}
 closeDatePicker();applyTheme();applyDocumentLocale();updateTitle();
 const pageKey=view==='calendar'?'page.calendar':'nav.'+view;
 app.innerHTML=`<div class="app-shell" data-interface-style="${state.settings.interfaceStyle}" data-resolved-mode="${document.body.dataset.resolvedMode}"><a class="skip-link" href="#main-content">${ht('nav.skip')}</a><aside class="sidebar"><a class="wordmark" href="#" data-action="nav" data-view="study">sela<span>.</span></a><p class="brand-note">${ht('brand.note')}</p><nav aria-label="${ht('nav.label')}">${[['study','timer'],['stats','chart'],['calendar','calendar'],['subjects','book']].map(([value,ic])=>`<button class="nav-item ${value===view?'active':''}" data-action="nav" data-view="${value}" ${value===view?'aria-current="page"':''}>${icon(ic)}<span>${ht('nav.'+value)}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-goal"><span>${ht('brand.patience')}</span><div class="progress"><span data-live="goal-bar" style="width:${Math.min(100,aggregate(state,dayKey(),dayKey()).total/(state.settings.goal*60000)*100)}%"></span></div><small>${ht('summary.goalLabel',{duration:formatDuration(state.settings.goal*60000)})}</small></div><button class="nav-item ${view==='settings'?'active':''}" data-action="nav" data-view="settings" aria-label="${ht('nav.settings')}">${icon('settings')}<span>${ht('nav.settings')}</span></button><div class="sidebar-meta"><span>${ht('storage.device')}</span><span>v1.0</span></div></div></aside><main id="main-content" class="main ${focused?'focused':''}"><header class="main-header"><div><h1 tabindex="-1">${ht(pageKey)}</h1><p data-live="current-date">${fmtDate(new Date(),{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</p></div><div class="header-actions"><select id="header-language-select" class="header-language" aria-label="${ht('settings.language')}">${LANGUAGES.map(l=>`<option value="${l.code}" lang="${l.code}" ${l.code===getLocale()?'selected':''}>${esc(l.name)}</option>`).join('')}</select>${button('quick-theme','',document.body.dataset.resolvedMode==='dark'?'sun':'moon','icon-btn',`aria-label="${ht(document.body.dataset.resolvedMode==='dark'?'mode.enableLight':'mode.enableDark')}" title="${ht('mode.toggle')}"`)}</div></header>${storageIssue?`<div class="storage-alert" role="alert">${esc(messageText(storageIssue))} ${button('export',t(unreadableRaw?'data.downloadOriginal':'data.export'),'','quiet')}${unreadableRaw?button('recover-local',t('data.startFresh'),'','quiet'):''}</div>`:''}<div class="view-content">${view==='study'?studyView():view==='stats'?statsView():view==='calendar'?heatmapCard(true):view==='subjects'?subjectsView():settingsView()}</div><footer class="main-footer"><span>${ht('brand.footer')}</span><span>${ht('brand.private')}</span></footer></main></div>`;
 renderedView=view;
 for(const draft of drafts){const field=app.querySelector(draft.selector);if(field)field.value=draft.value;}
 for(const [id,error] of formErrors){const field=app.querySelector('#'+id+' .form-error');if(field)field.textContent=messageText(error);}
 if(focusSelector){const field=app.querySelector(focusSelector);field?.focus({preventScroll:true});if(selection&&field?.setSelectionRange)try{field.setSelectionRange(...selection);}catch{}}
}
function validateForm(form){
 for(const field of Array.from(form.elements||[])){
  if(field.disabled||!['INPUT','SELECT','TEXTAREA'].includes(field.tagName))continue;
  let error=null;
  if(field.required&&!field.value.trim())error=new LocalisedError(field.name==='name'?'error.subjectName':field.name==='title'?'error.taskTitle':'validation.required');
  else if(field.matches('[data-local-date]'))try{parseDateInput(field.value);}catch(e){error=e;}
  else if(field.type==='email'&&field.value&&field.validity.typeMismatch)error=new LocalisedError('validation.email');
  else if(field.type==='url'&&field.value&&field.validity.typeMismatch)error=new LocalisedError('validation.url');
  else if(field.name==='goal'&&(field.validity.badInput||field.validity.rangeUnderflow||field.validity.rangeOverflow||field.validity.stepMismatch))error=new LocalisedError('error.goalRange');
  else if(field.minLength>0&&field.value.length<field.minLength)error=new LocalisedError('validation.short',{count:field.minLength});
  else if(field.maxLength>0&&field.value.length>field.maxLength)error=new LocalisedError('validation.long',{count:field.maxLength});
  if(error){field.setAttribute('aria-invalid','true');field.focus();throw error;}field.removeAttribute('aria-invalid');
 }
}
modal.addEventListener('close',()=>{uiEpoch++;closeDatePicker();modalContext=null;modal.innerHTML='';const target=modalOpener?app.querySelector(modalOpener):null;(target||app.querySelector('h1'))?.focus({preventScroll:true});modalOpener='';});
modal.addEventListener('cancel',e=>{if(modal.querySelector('.date-picker')){e.preventDefault();closeDatePicker({restoreFocus:true});}});
function drawModal(preserve=false){
 const context=modalContext;if(!context)return;
 const active=document.activeElement,fields=preserve?Array.from(modal.querySelectorAll('input,select,textarea')).map(field=>({name:field.name,value:field.value,checked:field.checked,dateValue:field.dataset.dateValue,dateValid:field.dataset.dateValid})):[];
 const focusName=modal.contains(active)?active.name:'',action=modal.contains(active)?active.dataset.action:'';let selection;try{if(active?.selectionStart!==null)selection=[active.selectionStart,active.selectionEnd];}catch{}
 closeDatePicker();
 modal.innerHTML=`<div class="modal-top"><h2 id="modal-title">${esc(typeof context.title==='function'?context.title():messageText(context.title))}</h2>${button('close-modal','','close','icon-btn',`aria-label="${ht('common.close')}"`)}</div>${context.body()}`;
 for(const saved of fields){const field=modal.querySelector(`[name="${saved.name}"]`);if(!field)continue;field.value=saved.dateValue&&saved.dateValid==='true'?formatDateInput(saved.dateValue):saved.value;field.checked=saved.checked;if(saved.dateValue){field.dataset.dateValue=saved.dateValue;field.dataset.dateValid=saved.dateValid;}}
 const form=modal.querySelector('form');
 if(form){form.noValidate=true;form.querySelectorAll('button[type="submit"]').forEach(b=>b.disabled=context.pending);form.setAttribute?.('aria-busy',String(context.pending));const error=modal.querySelector('.form-error');if(error)error.textContent=context.error?messageText(context.error):'';
  form.addEventListener('submit',async e=>{
   e.preventDefault();if(context.pending)return;
   try{validateForm(form);context.error=null;context.pending=true;form.querySelectorAll('button[type="submit"]').forEach(b=>b.disabled=true);form.setAttribute?.('aria-busy','true');await context.onSubmit(new FormData(form));if(modalContext===context)modal.close();}
   catch(err){context.error=err;if(modalContext===context){const error=modal.querySelector('.form-error');if(error)error.textContent=messageText(err);}else toast(err);}
   finally{context.pending=false;if(modalContext===context){const current=modal.querySelector('form');current?.querySelectorAll('button[type="submit"]').forEach(b=>b.disabled=false);current?.setAttribute?.('aria-busy','false');}}
  });
 }
 if(preserve){const target=focusName?modal.querySelector(`[name="${focusName}"]`):action?modal.querySelector(`[data-action="${action}"]`):null;target?.focus({preventScroll:true});if(selection&&target?.setSelectionRange)try{target.setSelectionRange(...selection);}catch{}}
}
function openModal(title,body,onSubmit){uiEpoch++;if(!modal.open)modalOpener=focusSelectorFor(document.activeElement);modalContext={title,body,onSubmit,pending:false,error:null};drawModal();if(!modal.open)modal.showModal();}
function confirmAction(title,text,label,fn){openModal(title,()=>`<p>${esc(typeof text==='function'?text():messageText(text))}</p><form novalidate><p class="form-error" role="alert"></p><div class="modal-actions">${button('close-modal',t('common.cancel'),'','quiet')}<button class="btn primary" type="submit">${esc(messageText(label))}</button></div></form>`,fn);}
function editSubject(id){
 const s=subject(id);
 openModal(message(s?'form.subjectEdit':'form.subjectNew'),()=>`<form novalidate><label class="field">${ht('form.subjectName')}<input name="name" maxlength="80" value="${esc(s?.name||'')}" placeholder="${ht('form.subjectExample')}" required autofocus></label><label class="field">${ht('form.colour')}<input name="color" type="color" value="${s?.color||COLORS[state.subjects.length%COLORS.length]}"></label><p class="form-error" role="alert"></p><div class="modal-actions">${button('close-modal',t('common.cancel'),'','quiet')}<button class="btn primary" type="submit">${ht('form.subjectSave')}</button></div></form>`,async fd=>{
  const name=fd.get('name').trim();if(!name)throw new LocalisedError('error.subjectName');
  await mutate(next=>{if(next.subjects.some(x=>x.id!==id&&!x.archived&&x.name.toLowerCase()===name.toLowerCase()))throw new LocalisedError('error.nameUsed');if(id)Object.assign(next.subjects.find(x=>x.id===id),{name,color:fd.get('color')});else{if(next.subjects.length>=LIMITS.subjects)throw new LocalisedError('error.subjectLimit');const item={id:uid(),name,color:fd.get('color')};next.subjects.push(item);if(!next.timer.subjectId)next.timer.subjectId=item.id;}});toast(message('toast.subjectSaved'));
 });
}
function editTask(id){
 const task=state.tasks.find(x=>x.id===id);
 openModal(message(task?'form.taskEdit':'form.taskNew'),()=>`<form novalidate><label class="field">${ht('form.taskTitle')}<input name="title" maxlength="300" value="${esc(task?.title||'')}" placeholder="${ht('form.taskExample')}" required autofocus></label><label class="field">${ht('table.subject')}<select name="subjectId">${subjectOptions(task?.subjectId||state.timer.subjectId,true)}</select></label><div class="field"><label for="task-edit-date">${ht('common.date')}</label>${dateField('task-edit-date','date',task?.date||taskDate,t('common.date'))}</div><p class="form-error" role="alert"></p><div class="modal-actions">${button('close-modal',t('common.cancel'),'','quiet')}<button class="btn primary" type="submit">${ht('form.taskSave')}</button></div></form>`,async fd=>{
  if(!fd.get('title').trim())throw new LocalisedError('error.taskTitle');const date=parseDateInput(fd.get('date'));
  await mutate(next=>{const item={title:fd.get('title').trim(),subjectId:fd.get('subjectId'),date};if(id)Object.assign(next.tasks.find(x=>x.id===id),item);else{if(next.tasks.length>=LIMITS.tasks)throw new LocalisedError('error.taskLimit');next.tasks.push({...item,id:uid(),done:false});}});toast(message('toast.taskSaved'));
 });
}
function showDay(date){const a=aggregate(state,date,date);openModal(()=>fmtDate(parseDay(date)),()=>`<div class="day-total"><strong>${formatClock(a.total)}</strong><span>${ht('count.sessions',{count:a.count})} · ${ht('stats.longest')} ${formatDuration(a.max)}</span></div>${subjectRows(a)}<div class="day-sessions">${timeline(a)}</div>${button('close-modal',t('common.close'),'','quiet')}`);}
function exportData(source=state){if(unreadableRaw){download(unreadableRaw,'sela-'+t('data.recoveryFilename')+'-'+dayKey()+'.json','application/json');toast(message('toast.originalExported'));return;}download(serializeBackup(source),`sela-${dayKey()}.json`,'application/json');toast(message('toast.exported'));}
function download(text,name,type){const url=URL.createObjectURL(new Blob([text],{type}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function shiftCursor(n,unit){if(unit==='month')cursor=monthDate(cursor,n);else cursor=addDays(cursor,n*(unit==='week'?7:1));}

async function handleAction(el){const action=el.dataset.action,id=el.dataset.id,v=el.dataset.value;
 if(action==='nav'){uiEpoch++;formErrors.clear();view=el.dataset.view;focused=false;render();window.scrollTo({top:0,behavior:'auto'});}
 else if(action==='toggle-timer'){await mutate(s=>{if(el.dataset.runId&&s.timer.runId!==el.dataset.runId)throw new LocalisedError('error.sessionChanged');return el.dataset.running==='true'?pauseTimer(s):startTimer(s);});}
 else if(action==='finish'){let ms;await mutate(s=>{if(el.dataset.runId&&s.timer.runId!==el.dataset.runId)throw new LocalisedError('error.sessionChanged');ms=finishTimer(s)});toast(message('toast.sessionFinished',{time:formatClock(ms)}));}
 else if(action==='focus'){focused=!focused;view='study';render();}
 else if(action==='quick-theme'){await mutate(s=>s.settings.theme=document.body.dataset.resolvedMode==='dark'?'light':'dark');}
 else if(action==='theme'){await mutate(s=>s.settings.theme=v);}
 else if(action==='task-filter'){taskFilter=v;render();}
 else if(action==='add-task'||action==='edit-task')editTask(id);
 else if(action==='delete-task')confirmAction(message('form.deleteTaskTitle'),message('form.deleteTaskText'),message('form.deleteTaskButton'),async()=>{await mutate(s=>s.tasks=s.tasks.filter(x=>x.id!==id));toast(message('toast.taskDeleted'));});
 else if(action==='add-subject'||action==='edit-subject')editSubject(id);
 else if(action==='choose-subject'){if(hasActiveSession(state)){toast(message('error.finishChoose'));return;}await mutate(s=>{if(hasActiveSession(s))throw new LocalisedError('error.finishChoose');if(!s.subjects.some(x=>x.id===id&&!x.archived))throw new LocalisedError('error.subjectUnavailable');s.timer.subjectId=id;});view='study';render();document.querySelector('#timer-heading')?.scrollIntoView({block:'center',behavior:'smooth'});}
 else if(action==='delete-subject'){if(state.timer.subjectId===id&&hasActiveSession(state)){toast(message('error.finishArchive'));return;}confirmAction(message('form.archiveTitle'),message('form.archiveText'),message('form.archiveButton'),async()=>{await mutate(s=>{if(s.timer.subjectId===id&&hasActiveSession(s))throw new LocalisedError('error.finishArchive');s.subjects.find(x=>x.id===id).archived=true;if(s.timer.subjectId===id)s.timer.subjectId=s.subjects.find(x=>!x.archived)?.id||'';});toast(message('toast.subjectArchived'));});}
 else if(action==='restore-subject')await mutate(s=>{const restored=s.subjects.find(x=>x.id===id);if(s.subjects.some(x=>!x.archived&&x.id!==id&&x.name.toLowerCase()===restored.name.toLowerCase()))throw new LocalisedError('error.restoreName');restored.archived=false;if(!s.timer.subjectId)s.timer.subjectId=restored.id;});
 else if(action==='heat-mode'){heatMode=v;render();}
 else if(action==='heat-prev'||action==='heat-next'){shiftCursor(action==='heat-prev'?-1:1,heatMode);render();}
 else if(action==='day-detail')showDay(el.dataset.date);
 else if(action==='period'){period=v;render();}
 else if(action==='period-prev'||action==='period-next'){shiftCursor(action==='period-prev'?-1:1,period);render();}
 else if(action==='period-today'){cursor=new Date();render();}
 else if(action==='close-modal')modal.close();
 else if(action==='export')await withStudyLock(()=>exportData(unreadableRaw||memoryOnly?state:latestState()));
 else if(action==='recover-local'){const expectedRaw=storedRaw;confirmAction(message('form.resetTitle'),message('form.resetText'),message('form.resetButton'),async()=>{await replaceData(newState(),{recover:true,expectedRaw});toast(message('toast.reset'));});}
 else if(action==='import')document.querySelector('#import-file').click();
 else if(action==='cloud-save'||action==='cloud-load'){
  if(action==='cloud-load'&&hasActiveSession(state)){toast(message('error.finishCloud'));return;}
  const epoch=uiEpoch;
  await withCloudOperation(action==='cloud-save'?'save':'load',async()=>{
   const remote=await cloud.load();
   if(uiEpoch!==epoch||view!=='settings'||modal.open){toast(message('toast.cloudCancelled'));return;}
   if(action==='cloud-save')confirmAction(message('form.cloudSaveTitle'),message(remote.data?'form.cloudSaveExisting':'form.cloudSaveNew'),message('form.cloudSaveButton'),async()=>{await withCloudOperation('save',async()=>{const copy=await withStudyLock(()=>backupState(latestState()));await cloud.save(copy,remote.revision,remote.context);toast(message('toast.cloudSaved'));});});
   else{
    if(!remote.data){toast(message('toast.cloudEmpty'));return;}
    const next=validateState(remote.data);next.timer.startedAt=null;next.timer.elapsedMs=0;next.timer.runId=uid();
    confirmAction(message('form.cloudLoadTitle'),message('form.cloudLoadText'),message('form.cloudLoadButton'),async()=>{await withCloudOperation('load',async()=>{await cloud.checkContext(remote.context);await replaceData(next,{beforeReplace:()=>cloud.assertCurrentContext(remote.context)});toast(message('toast.cloudLoaded'));});});
   }
  });
 }
 else if(action==='cloud-out')await withCloudOperation('out',async()=>{await cloud.signOut();cloudStatus=message('cloud.signedOut');toast(cloudStatus);});
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();if(el.disabled)return;Promise.resolve(handleAction(el)).catch(err=>toast(err));});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.id==='language-select'||el.id==='header-language-select'){setLocale(el.value);return;}if(el.dataset.task)await mutate(s=>s.tasks.find(x=>x.id===el.dataset.task).done=el.checked);else if(el.id==='timer-subject')await mutate(s=>{if(hasActiveSession(s))throw new LocalisedError('error.finishChange');s.timer.subjectId=el.value;});else if(el.id==='task-date'){taskDate=el.value?parseDateInput(el.value):dayKey();render();}else if(el.id==='theme-select')await mutate(s=>s.settings.themeKey=el.value);else if(el.id==='interface-select')await mutate(s=>s.settings.interfaceStyle=el.value);else if(el.id==='import-file'){try{const file=el.files[0];if(!file)return;if(hasActiveSession(state))throw new LocalisedError('error.finishImport');if(file.size>MAX_BACKUP_BYTES)throw new LocalisedError('error.importTooLarge');const request=++importEpoch,epoch=uiEpoch,text=await file.text();if(request!==importEpoch||uiEpoch!==epoch||modal.open)return;const next=parseBackup(text);next.timer.startedAt=null;next.timer.elapsedMs=0;next.timer.runId=uid();confirmAction(message('form.importTitle'),()=>t('form.importText',{subjects:t('count.subjects',{count:next.subjects.length}),records:t('count.records',{count:next.sessions.length})}),message('form.importButton'),async()=>{await replaceData(next);toast(message('toast.imported'));});}catch(err){toast(err);}finally{el.value='';}}}catch(err){if(el.matches?.('[data-local-date]'))el.setAttribute('aria-invalid','true');toast(err);}});
document.addEventListener('submit',async e=>{if(!['goal-form','cloud-config','cloud-auth'].includes(e.target.id))return;e.preventDefault();const fd=new FormData(e.target);try{validateForm(e.target);formErrors.delete(e.target.id);const error=e.target.querySelector?.('.form-error');if(error)error.textContent='';if(e.target.id==='goal-form'){const goal=Number(fd.get('goal'));if(!Number.isInteger(goal)||goal<15||goal>1440)throw new LocalisedError('error.goalRange');await mutate(s=>s.settings.goal=goal);toast(message('toast.goalSaved'));}else if(e.target.id==='cloud-config'){if(authPending||cloudPending)throw new LocalisedError('error.cloudBusy');cloud.configure(fd.get('url'),fd.get('key'));cloudStatus='';render({discardDrafts:['cloud-config']});toast(message('toast.configSaved'));}else{
 if(authPending)return;if(cloudPending)throw new LocalisedError('error.cloudBusy');
 const form=e.target,submit=e.submitter;authPending=true;
 const toggleButtons=disabled=>{form.querySelectorAll('button[type="submit"]').forEach(x=>x.disabled=disabled);document.querySelectorAll('#cloud-auth button[type="submit"]').forEach(x=>x.disabled=disabled);};
 toggleButtons(true);render();
 try{cloudStatus=await cloud.authenticate(fd.get('email'),fd.get('password'),submit?.value||'login');const status=document.querySelector('#cloud-status');if(status)status.textContent=messageText(cloudStatus);toast(cloudStatus);}
 catch(err){cloudStatus=err;const status=document.querySelector('#cloud-status');if(status)status.textContent=messageText(cloudStatus);throw err;}
 finally{authPending=false;toggleButtons(false);const password=form.querySelector('input[name="password"]');if(password)password.value='';const current=document.querySelector('#cloud-auth input[name="password"]');if(current)current.value='';render();}
}}catch(err){formErrors.set(e.target.id,err);const error=e.target.querySelector?.('.form-error');if(error)error.textContent=messageText(err);toast(err);}});
window.addEventListener('storage',e=>{if(e.key==='sela.supabase.config.v1'){cloudStatus='';if(view==='settings')render();return;}if(e.key!==KEY&&e.key!==null)return;if(memoryOnly){toast(message('error.tabChanged'));return;}try{const raw=localStorage.getItem(KEY),restored=restoreLocalState(raw);state=restored.state;storedRaw=raw;storageIssue='';unreadableRaw='';render();if(restored.reset)mutate(()=>{}).catch(err=>toast(err));}catch{toast(message('error.tabUnreadable'));}});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(state.settings.theme==='system')render();});
function tick(){
 const now=Date.now(),todayKey=dayKey(now),rolledOver=todayKey!==calendarToday;
 if(rolledOver){if(taskDate===calendarToday)taskDate=todayKey;if(dayKey(cursor)===calendarToday)cursor=parseDay(todayKey);calendarToday=todayKey;if(view!=='settings')render();}
 const a=aggregate(state,todayKey,todayKey,now);
 const set=(key,text)=>{const node=app.querySelector('[data-live="'+key+'"]');if(node)node.textContent=text;};
 set('current-date',fmtDate(now,{weekday:'long',day:'numeric',month:'long',year:'numeric'}));
 set('session-count',t('count.sessions',{count:a.count}));set('max-focus',formatDuration(a.max));
 set('timer',formatClock(elapsed(state,now)));set('today',formatClock(a.total));set('today-minutes',formatNumber(Math.floor(a.total/60000)));set('goal-percent',formatPercent(Math.min(1,a.total/(state.settings.goal*60000))));
 const bar=app.querySelector('[data-live="goal-bar"]');if(bar)bar.style.width=Math.min(100,a.total/(state.settings.goal*60000)*100)+'%';
 app.querySelectorAll('[data-today-subjects] [data-subject-time]').forEach(el=>el.textContent=formatDuration(a.subjects[el.dataset.subjectTime]||0));
 app.querySelectorAll('[data-today-subjects] [data-subject-progress]').forEach(el=>el.style.width=(a.total?(a.subjects[el.dataset.subjectProgress]||0)/a.total*100:0)+'%');
 app.querySelectorAll('.heat-cell.today').forEach(el=>{if(el.dataset.date!==todayKey)return;for(let i=0;i<5;i++)el.classList.toggle('l'+i,level(a.total)===i);el.title=fmtDate(now)+' · '+formatDuration(a.total);el.setAttribute('aria-label',t('calendar.dayLabel',{date:fmtDate(now),time:formatClock(a.total)}));});
 if(heatMode==='week'||heatMode==='month'){
  const from=heatMode==='week'?localeWeekStart(cursor):monthDate(cursor),to=heatMode==='week'?addDays(from,6):monthDate(cursor,1,0);
  const heat=aggregate(state,dayKey(from),dayKey(to),now);
  app.querySelectorAll('[data-heat-day]').forEach(el=>el.textContent=formatDuration(heat.days[el.dataset.heatDay]||0));
  set('heat-total',t(heatMode==='week'?'calendar.weekTotal':'calendar.monthTotal',{duration:formatDuration(heat.total)}));
 }
 const running=state.timer.startedAt!==null;updateTitle();
 if(running){const finish=app.querySelector('[data-action="finish"]');if(finish)finish.disabled=false;}
 if(rolledOver||running&&Math.floor(now/1000)%30===0)set('streak',t('summary.streak',{count:streak(state,now)}));
 if(running&&view==='stats'&&!modal.open&&Math.floor(now/1000)%30===0)render();
}
onLocaleChange(()=>{render();if(modal.open)drawModal(true);if(toastMessage)document.querySelector('#toast').textContent=messageText(toastMessage);});
initDateInputs();
setInterval(tick,1000);
render();
if(needsReset)mutate(()=>{}).catch(err=>toast(err));
